SELECT      T0.[ItemCode] AS 'Item No.',    T0.[ItemName] AS 'Item Description',        -- Tên Item Group    T0.[ItmsGrpCod] AS 'Item Group Code',    T1.[ItmsGrpNam] AS 'Item Group Name',        -- Lấy Tài khoản Kho (Ưu tiên theo Item Group hoặc Warehouse)    CASE T0.[GLMethod]         WHEN 'C' THEN T1.[BalInvntAc] -- Nhóm vật tư (OITB)        WHEN 'W' THEN T2.[BalInvntAc] -- Kho (OITW)        ELSE NULL     END AS 'Inventory Account',     -- Lấy Tài khoản Giá vốn (Ưu tiên theo Item Group hoặc Warehouse)    CASE T0.[GLMethod]         WHEN 'C' THEN T1.[SaleCostAc] -- Nhóm vật tư (OITB)        WHEN 'W' THEN T2.[SaleCostAc] -- Kho (OITW)        ELSE NULL     END AS 'COGS Account',                 -- Giá vốn Item     T2.[AvgPrice] AS 'Item Cost',        -- Procurement Method    CASE T0.[PrcrmntMtd]         WHEN 'B' THEN 'Buy (Mua)'         WHEN 'M' THEN 'Make (Sản xuất)'         ELSE T0.[PrcrmntMtd]     END AS 'Procurement Method',        -- Đơn vị đo lường (UoM)    T0.[InvntryUom] AS 'Inventory / Production UoM',    T0.[BuyUnitMsr] AS 'Purchasing UoM',    T0.[NumInBuy] AS 'No. of Items per Purchase Unit',    T0.[SalUnitMsr] AS 'Sales UoM',    T0.[NumInSale] AS 'No. of Items per Sales Unit',        -- Kho mặc định    T0.[DfltWH] AS 'Default Warehouse',        -- Tổng tồn kho hiện tại theo từng kho    T2.[WhsCode] AS 'Warehouse Code',    T2.[OnHand] AS 'Current Stock (Qty)'FROM [dbo].[OITM] T0LEFT JOIN [dbo].[OITB] T1 ON T0.[ItmsGrpCod] = T1.[ItmsGrpCod]LEFT JOIN [dbo].[OITW] T2 ON T0.[ItemCode] = T2.[ItemCode]ORDER BY T0.[ItemCode], T2.[WhsCode]